pragma solidity >=0.8.0;
contract EventOrderPackM3 {
    event Mark(uint8 indexed tag, string indexed s, bytes b);
    uint8 public lo;
    uint8 public hi;
    string public s1;
    bytes public b1;
    function mix() external {
        lo = 127;
        hi = 128;
        s1 = "a";
        b1 = hex"00";
        emit Mark(127, s1, b1);
        emit Mark(128, s1, b1);
    }
    function getAll() external view returns (uint8, uint8, string memory, bytes memory) {
        return (lo, hi, s1, b1);
    }
}
